package com.powerliq.publisher;
import java.util.*;import org.slf4j.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.transaction.*;import org.springframework.transaction.support.TransactionTemplate;import software.amazon.awssdk.services.eventbridge.EventBridgeClient;import software.amazon.awssdk.services.eventbridge.model.*;
public class OutboxEventPublisher{
 private static final Logger LOG=LoggerFactory.getLogger(OutboxEventPublisher.class);private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final EventBridgeClient client;private final String bus,table,source;private final int batchSize,maxAttempts;
 OutboxEventPublisher(JdbcTemplate j,PlatformTransactionManager tm,EventBridgeClient c,String b,String t,String s,int batchSize,int maxAttempts){if(!t.matches("[a-z_]+"))throw new IllegalArgumentException("Unsafe event table");if(batchSize<1||batchSize>100||maxAttempts<1||maxAttempts>100)throw new IllegalArgumentException("Event publisher bounds are invalid");jdbc=j;tx=new TransactionTemplate(tm);client=c;bus=b;table=t;source=s;this.batchSize=batchSize;this.maxAttempts=maxAttempts;}
 @Scheduled(fixedDelayString="${powerliq.events.publisher-delay:1000}") public void publish(){for(int i=0;i<batchSize;i++){Boolean found=tx.execute(status->publishOne());if(!Boolean.TRUE.equals(found))break;}}
 private boolean publishOne(){var rows=jdbc.query("SELECT event_id,event_type,payload FROM "+table+" WHERE published_at IS NULL AND attempts<? ORDER BY occurred_at,event_id LIMIT 1 FOR UPDATE SKIP LOCKED",(r,n)->new Row(r.getObject(1,UUID.class),r.getString(2),r.getString(3)),maxAttempts);if(rows.isEmpty())return false;Row row=rows.getFirst();try{PutEventsResponse response=client.putEvents(PutEventsRequest.builder().entries(PutEventsRequestEntry.builder().eventBusName(bus).source("com.powerliq."+source).detailType(row.type()).detail(row.payload()).build()).build());if(response.failedEntryCount()>0)throw new IllegalStateException(response.entries().getFirst().errorCode());jdbc.update("UPDATE "+table+" SET published_at=now(),attempts=attempts+1,last_error=NULL WHERE event_id=?",row.id());}catch(Exception e){jdbc.update("UPDATE "+table+" SET attempts=attempts+1,last_error=? WHERE event_id=?",truncate(e.getMessage()),row.id());LOG.warn("Event publication failed eventId={} attempt will retry",row.id(),e);}return true;}
 private String truncate(String s){return s==null?"unknown":s.substring(0,Math.min(1000,s.length()));}private record Row(UUID id,String type,String payload){}
}
